import * as React from 'react'
import Layout from "../components/layout"
import Seo from "../components/seo"

// ── Outcome helpers ────────────────────────────────────────────────────────────

const OUTCOME_LABEL = { H: "Home", D: "Draw", A: "Away" }
const OUTCOME_CLS = {
    H: "bg-green-100 text-green-800 border-green-200 dark:bg-green-900 dark:text-green-200 dark:border-green-700",
    D: "bg-amber-100 text-amber-800 border-amber-200 dark:bg-amber-900 dark:text-amber-200 dark:border-amber-700",
    A: "bg-red-100  text-red-800  border-red-200  dark:bg-red-900  dark:text-red-200  dark:border-red-700",
}

function OutcomeBadge({ outcome }) {
    return (
        <span className={`inline-block px-2 py-0.5 rounded-full text-xs font-bold border ${OUTCOME_CLS[outcome]}`}>
            {OUTCOME_LABEL[outcome]}
        </span>
    )
}

function ProbBar({ label, pct, color }) {
    return (
        <div className="flex items-center gap-2">
            <span className="text-xs text-gray-500 dark:text-gray-400 w-16">{label}</span>
            <div className="flex-1 bg-gray-100 dark:bg-slate-600 rounded-full h-2">
                <div className={`h-2 rounded-full ${color}`} style={{ width: `${Math.min(pct, 100)}%` }} />
            </div>
            <span className="text-xs font-mono w-8 text-right text-gray-600 dark:text-gray-300">{pct}%</span>
        </div>
    )
}

// ── Features table ─────────────────────────────────────────────────────────────

const sign = v => `${v > 0 ? '+' : ''}${v.toFixed(1)}`
const pct  = v => `${(v * 100).toFixed(0)}%`
const f1   = v => v.toFixed(1)
const f2   = v => v.toFixed(2)
const int  = v => Math.round(v)

// [label, home_key, away_key, formatter, higherIsBetter, source ('raw'|'exp_raw')]
const FEATS = [
    // ── Global ──────────────────────────────────────────────────────────────
    ["ELO rating",               "elo_home",                    "elo_away",                   int,  true,  'raw'],
    ["Season PPG",               "home_ppg",                    "away_ppg",                   f2,   true,  'raw'],
    ["Games played",             "home_n_games",                "away_n_games",               int,  false, 'raw'],
    // ── Last 5 ──────────────────────────────────────────────────────────────
    ["Win ratio (last 5)",       "home_win_ratio",              "away_win_ratio",              pct,  true,  'raw'],
    ["Avg score (last 5)",       "home_avg_score",              "away_avg_score",              f1,   true,  'raw'],
    ["Avg conceded (last 5)",    "home_avg_conc",               "away_avg_conc",               f1,   false, 'raw'],
    ["Avg margin (last 5)",      "home_avg_margin",             "away_avg_margin",             sign, true,  'raw'],
    ["Try rate (last 5)",        "home_try_rate",               "away_try_rate",               pct,  true,  'raw'],
    ["Avg possession (last 5)",  "home_avg_poss",               "away_avg_poss",               pct,  true,  'raw'],
    ["Avg kicks (last 5)",       "home_avg_kicks",              "away_avg_kicks",              f1,   false, 'raw'],
    ["Avg penalties (last 5)",   "home_avg_pen",                "away_avg_pen",                f1,   false, 'raw'],
    ["Avg yellow cards (last 5)","home_avg_yellow",             "away_avg_yellow",             f1,   false, 'raw'],
    ["Avg red cards (last 5)",   "home_avg_red",                "away_avg_red",                f1,   false, 'raw'],
    // ── Venue ───────────────────────────────────────────────────────────────
    ["Venue win ratio (last 5)", "home_venue_win_ratio",        "away_venue_win_ratio",        pct,  true,  'raw'],
    ["Venue avg margin (last 5)","home_venue_avg_margin",       "away_venue_avg_margin",       sign, true,  'raw'],
]

// Derived features (lineup model only) — single diff value, positive = home advantage
const DERIVED_FEATS = [
    ["ELO adj. by lineup quality",  "lineup_adj_elo_diff"],
    ["ELO × lineup interaction",    "elo_lineup_interaction"],
    ["Disruption diff",             "disruption_diff"],
    ["Charnière vs lineup diff",    "charniere_vs_total_diff"],
    ["Fwd dominance diff",          "fwd_dominance_diff"],
]

// Experience features (lineup model only)
const EXP_FEATS = [
    ["Lineup avg games played",    "lineup_h_avg_games_played",    "lineup_a_avg_games_played",    f1, true],
    ["Lineup avg starts",          "lineup_h_avg_starts",          "lineup_a_avg_starts",          f1, true],
    ["Subs avg games played",      "subs_h_avg_games_played",      "subs_a_avg_games_played",      f1, true],
    ["Charnière (9&10) avg games", "charniere_h_avg_games_played", "charniere_a_avg_games_played", f1, true],
    ["Charnière (9&10) avg starts","charniere_h_avg_starts",       "charniere_a_avg_starts",       f1, true],
    ["Forwards (1-8) avg games",   "forwards_h_avg_games_played",  "forwards_a_avg_games_played",  f1, true],
    ["Forwards (1-8) avg starts",  "forwards_h_avg_starts",        "forwards_a_avg_starts",        f1, true],
    ["Backs (11-15) avg games",    "backs_h_avg_games_played",     "backs_a_avg_games_played",     f1, true],
    ["Backs (11-15) avg starts",   "backs_h_avg_starts",           "backs_a_avg_starts",           f1, true],
    ["Total squad avg games",      "total_h_avg_games_played",     "total_a_avg_games_played",     f1, true],
]

// ── Shared feature table ───────────────────────────────────────────────────────

function FeatureRow([label, hk, ak, fmt, higherBetter], src, match, fi) {
    const bag = src === 'exp_raw' ? (match.exp_raw || {}) : match.raw
    const hv = bag[hk], av = bag[ak]
    const both = hv != null && av != null
    const hBetter = both && (higherBetter ? hv > av : hv < av)
    const aBetter = both && (higherBetter ? av > hv : av < hv)
    return (
        <tr key={fi} className="border-t border-gray-50 dark:border-slate-600 hover:bg-gray-50 dark:hover:bg-slate-600">
            <td className="px-4 py-2 text-xs text-gray-500 dark:text-gray-400">{label}</td>
            <td className={`px-4 py-2 text-center font-mono text-xs ${hBetter ? 'font-bold text-green-700 dark:text-green-400' : 'text-gray-700 dark:text-gray-300'}`}>
                {hv != null ? fmt(hv) : '—'}
            </td>
            <td className={`px-4 py-2 text-center font-mono text-xs ${aBetter ? 'font-bold text-green-700 dark:text-green-400' : 'text-gray-700 dark:text-gray-300'}`}>
                {av != null ? fmt(av) : '—'}
            </td>
        </tr>
    )
}

function DerivedRow([label, key], match, fi) {
    const v = (match.derived || {})[key]
    if (v == null) return null
    const isPos = v > 0.005
    const isNeg = v < -0.005
    return (
        <tr key={fi} className="border-t border-gray-50 dark:border-slate-600 hover:bg-gray-50 dark:hover:bg-slate-600">
            <td className="px-4 py-2 text-xs text-gray-500 dark:text-gray-400">{label}</td>
            <td colSpan={2} className={`px-4 py-2 text-center font-mono text-xs font-bold
                ${isPos ? 'text-green-700 dark:text-green-400' : isNeg ? 'text-red-600 dark:text-red-400' : 'text-gray-500 dark:text-gray-400'}`}>
                {v > 0 ? '+' : ''}{v.toFixed(2)}
                <span className="ml-1 font-normal text-gray-400">{isPos ? '← home' : isNeg ? 'away →' : 'even'}</span>
            </td>
        </tr>
    )
}

function FeatureTable({ match }) {
    const hasExp = match.lineup_available && match.exp_raw && Object.keys(match.exp_raw).length > 0
    const hasDerived = match.lineup_available && match.derived && Object.keys(match.derived).length > 0
    const wx = match.weather || {}
    const hasWeather = (wx.rain_mm ?? 0) > 0 || (wx.wind_speed_kmh ?? 0) > 0 || wx.temperature_c !== null && wx.temperature_c !== undefined
    return (
        <table className="w-full">
            <thead>
                <tr className="bg-gray-50 dark:bg-slate-600 text-xs text-gray-400">
                    <th className="px-4 py-2 text-left">Metric</th>
                    <th className="px-4 py-2 text-center">{match.home}</th>
                    <th className="px-4 py-2 text-center">{match.away}</th>
                </tr>
            </thead>
            <tbody>
                {FEATS.map((feat, fi) => FeatureRow(feat, feat[5], match, fi))}
                {hasExp && <>
                    <tr className="bg-blue-50 dark:bg-slate-600 border-t border-gray-100 dark:border-slate-500">
                        <td colSpan={3} className="px-4 py-1.5 text-xs font-bold text-blue-600 dark:text-blue-300">★ Lineup experience features</td>
                    </tr>
                    {EXP_FEATS.map((feat, fi) => FeatureRow(feat, 'exp_raw', match, fi))}
                </>}
                {hasDerived && <>
                    <tr className="bg-purple-50 dark:bg-slate-600 border-t border-gray-100 dark:border-slate-500">
                        <td colSpan={3} className="px-4 py-1.5 text-xs font-bold text-purple-600 dark:text-purple-300">⚡ Derived model features</td>
                    </tr>
                    {DERIVED_FEATS.map((feat, fi) => DerivedRow(feat, match, fi))}
                </>}
                {hasWeather && <>
                    <tr className="bg-sky-50 dark:bg-slate-600 border-t border-gray-100 dark:border-slate-500">
                        <td colSpan={3} className="px-4 py-1.5 text-xs font-bold text-sky-600 dark:text-sky-300">🌦 Match-day weather (kickoff)</td>
                    </tr>
                    <tr className="text-xs border-t border-gray-50 dark:border-slate-600">
                        <td className="px-4 py-1.5 text-gray-500 dark:text-gray-400">Rain</td>
                        <td colSpan={2} className="px-4 py-1.5 text-center font-mono text-gray-700 dark:text-gray-200">{wx.rain_mm ?? 0} mm</td>
                    </tr>
                    <tr className="text-xs border-t border-gray-50 dark:border-slate-600 bg-gray-50/30 dark:bg-slate-700/30">
                        <td className="px-4 py-1.5 text-gray-500 dark:text-gray-400">Wind</td>
                        <td colSpan={2} className="px-4 py-1.5 text-center font-mono text-gray-700 dark:text-gray-200">{wx.wind_speed_kmh ?? 0} km/h</td>
                    </tr>
                    {wx.temperature_c !== null && wx.temperature_c !== undefined && (
                    <tr className="text-xs border-t border-gray-50 dark:border-slate-600">
                        <td className="px-4 py-1.5 text-gray-500 dark:text-gray-400">Temperature</td>
                        <td colSpan={2} className="px-4 py-1.5 text-center font-mono text-gray-700 dark:text-gray-200">{wx.temperature_c}°C</td>
                    </tr>
                    )}
                </>}
            </tbody>
        </table>
    )
}

// ── Match card ─────────────────────────────────────────────────────────────────

function weatherEmoji(rain, wind, temp) {
    if (rain >= 5) return "⛈"
    if (rain >= 1) return "🌧"
    if (wind >= 50) return "🌬"
    if (temp !== null && temp <= 5) return "🥶"
    if (temp !== null && temp >= 30) return "🥵"
    return "☀️"
}

function WeatherStrip({ weather }) {
    if (!weather) return null
    const rain = weather.rain_mm ?? 0
    const wind = weather.wind_speed_kmh ?? 0
    const temp = weather.temperature_c ?? null
    if (rain === 0 && wind === 0 && temp === null) return null
    const emoji = weatherEmoji(rain, wind, temp)
    const parts = []
    if (rain > 0) parts.push(`🌧 ${rain} mm`)
    if (wind >= 20) parts.push(`💨 ${Math.round(wind)} km/h`)
    if (temp !== null) parts.push(`🌡️ ${temp}°C`)
    return (
        <div className="flex items-center justify-center gap-3 text-xs text-sky-600 dark:text-sky-300 bg-sky-50 dark:bg-sky-900/20 rounded-lg px-3 py-1.5 mb-3">
            <span className="text-base">{emoji}</span>
            {parts.map((p, i) => <span key={i} className="font-mono">{p}</span>)}
        </div>
    )
}

function MatchCard({ match }) {
    const primary = match.lineup_available ? match.lineup : match.base
    const [open, setOpen] = React.useState(false)
    return (
        <div className="bg-white dark:bg-slate-700 rounded-xl shadow-sm border border-gray-100 dark:border-slate-600 mb-4 overflow-hidden">
            <div className="p-5">
                <div className="flex items-center justify-between mb-4">
                    <div className="text-base font-bold text-gray-900 dark:text-white flex-1">{match.home}</div>
                    <div className="text-gray-300 dark:text-gray-500 px-3 font-light">vs</div>
                    <div className="text-base font-bold text-gray-900 dark:text-white flex-1 text-right">{match.away}</div>
                </div>

                <WeatherStrip weather={match.weather} />

                <div className="text-center mb-4">
                    <OutcomeBadge outcome={primary.outcome} />
                    <span className="ml-2 text-xl font-mono font-bold text-gray-800 dark:text-gray-100">
                        {Math.round(primary.pred_home)} – {Math.round(primary.pred_away)}
                    </span>
                </div>

                <div className="space-y-1.5 mb-3">
                    <ProbBar label="Home" pct={primary.prob_h} color="bg-green-500" />
                    <ProbBar label="Draw" pct={primary.prob_d} color="bg-amber-400" />
                    <ProbBar label="Away" pct={primary.prob_a} color="bg-red-500" />
                </div>

                {match.lineup_available && (
                    <div className="border-t border-gray-100 dark:border-slate-600 pt-3 mt-3 grid grid-cols-2 gap-3 text-sm">
                        <div className="text-center">
                            <div className="text-xs text-gray-400 mb-1">Base model</div>
                            <div className="font-mono font-bold text-gray-700 dark:text-gray-200">
                                {Math.round(match.base.pred_home)}–{Math.round(match.base.pred_away)}
                            </div>
                            <div className="mt-1"><OutcomeBadge outcome={match.base.outcome} /></div>
                            <div className="text-xs text-gray-400 mt-1">
                                {match.base.prob_h}%H · {match.base.prob_d}%D · {match.base.prob_a}%A
                            </div>
                        </div>
                        <div className="text-center">
                            <div className="text-xs text-blue-500 mb-1">★ With lineups</div>
                            <div className="font-mono font-bold text-gray-700 dark:text-gray-200">
                                {Math.round(match.lineup.pred_home)}–{Math.round(match.lineup.pred_away)}
                            </div>
                            <div className="mt-1"><OutcomeBadge outcome={match.lineup.outcome} /></div>
                            <div className="text-xs text-gray-400 mt-1">
                                {match.lineup.prob_h}%H · {match.lineup.prob_d}%D · {match.lineup.prob_a}%A
                            </div>
                        </div>
                    </div>
                )}

                <div className="mt-3 flex items-center justify-between">
                    {match.lineup_available
                        ? <span className="text-xs text-blue-500 font-medium">★ Lineups available</span>
                        : <span className="text-xs text-gray-400">No lineup data yet</span>
                    }
                    <button
                        onClick={() => setOpen(o => !o)}
                        className="text-xs text-gray-400 hover:text-red-900 dark:hover:text-white transition-colors flex items-center gap-1"
                    >
                        Features {open ? '▾' : '▸'}
                    </button>
                </div>
            </div>

            {open && (
                <div className="border-t border-gray-100 dark:border-slate-600">
                    <FeatureTable match={match} />
                </div>
            )}
        </div>
    )
}

// ── Tabs ───────────────────────────────────────────────────────────────────────

function PredictionsTab({ current }) {
    const champ = current.champ === 'top14' ? 'Top 14' : 'Pro D2'
    const d = new Date(current.gen_at)
    const fmt = isNaN(d) ? '' : d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long' })
    return (
        <div>
            <div className="mb-5">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                    {champ} — Journée {current.day}
                </h2>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                    Season {current.season}{fmt ? ` · ${fmt}` : ''}
                </p>
            </div>
            {current.matches.map((m, i) => <MatchCard key={i} match={m} />)}
        </div>
    )
}

function acc(ok, n) {
    return n ? `${Math.round(100 * ok / n)}%` : '—'
}

function StatCard({ value, label, sub, bold = false }) {
    return (
        <div className="bg-white dark:bg-slate-700 rounded-xl border border-gray-100 dark:border-slate-600 p-4 text-center">
            <div className={`text-3xl font-bold ${bold ? 'text-red-900 dark:text-white' : 'text-gray-800 dark:text-white'}`}>{value}</div>
            <div className="text-sm text-gray-500 dark:text-gray-400 mt-1">{label}</div>
            {sub && <div className="text-xs text-gray-400 mt-0.5">{sub}</div>}
        </div>
    )
}

function HistoryTab({ history, stats }) {
    const [openMatch, setOpenMatch] = React.useState(null)

    if (!history.length) {
        return (
            <p className="text-gray-400 text-center py-12">
                Results will appear here after the first matchday.
            </p>
        )
    }

    return (
        <div>
            {/* Overall accuracy */}
            <div className="grid grid-cols-2 gap-3 mb-3">
                <StatCard
                    value={acc(stats.base_ok, stats.n)}
                    label="Base model"
                    sub={`${stats.base_ok} / ${stats.n} matches`}
                />
                <StatCard
                    value={acc(stats.lineup_ok, stats.n)}
                    label="With lineups ★"
                    sub={`${stats.lineup_ok} / ${stats.n} matches`}
                    bold
                />
            </div>

            {/* Home / Draw / Away breakdown */}
            <div className="grid grid-cols-3 gap-3 mb-6">
                <StatCard
                    value={acc(stats.home.base_ok, stats.home.total)}
                    label="Home wins"
                    sub={`${stats.home.base_ok} / ${stats.home.total}`}
                />
                <StatCard
                    value={acc(stats.draw.base_ok, stats.draw.total)}
                    label="Draws"
                    sub={`${stats.draw.base_ok} / ${stats.draw.total}`}
                />
                <StatCard
                    value={acc(stats.away.base_ok, stats.away.total)}
                    label="Away wins"
                    sub={`${stats.away.base_ok} / ${stats.away.total}`}
                />
            </div>

            {/* Per-round tables */}
            {[...history].reverse().map((round, ri) => {
                const champ = round.champ === 'top14' ? 'Top 14' : 'Pro D2'
                const roundAcc = acc(round.base_correct, round.total)
                return (
                    <div key={ri} className="bg-white dark:bg-slate-700 rounded-xl border border-gray-100 dark:border-slate-600 mb-4 overflow-hidden">
                        <div className="bg-gray-50 dark:bg-slate-600 px-4 py-2 border-b border-gray-100 dark:border-slate-500 flex items-center justify-between">
                            <div>
                                <span className="font-semibold text-gray-700 dark:text-white">{champ} — Journée {round.day}</span>
                                <span className="text-gray-400 text-sm ml-2">· {round.season}</span>
                            </div>
                            <span className="text-sm font-semibold text-gray-600 dark:text-gray-300">
                                {round.base_correct}/{round.total} ({roundAcc})
                            </span>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="text-xs text-gray-400 bg-gray-50 dark:bg-slate-600 border-b border-gray-100 dark:border-slate-500">
                                        <th className="px-3 py-2 text-left">Home</th>
                                        <th className="px-3 py-2 text-left">Away</th>
                                        <th className="px-3 py-2 text-center">Pred. score</th>
                                        <th className="px-3 py-2 text-center">Pred. outcome</th>
                                        <th className="px-3 py-2 text-center">Result</th>
                                        <th className="px-3 py-2 text-center">✓</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {round.matches.map((m, mi) => {
                                        const primary = m.lineup_available ? m.lineup : m.base
                                        const act = m.actual
                                        const correct = m.base_correct
                                        const key = `${ri}-${mi}`
                                        const isOpen = openMatch === key
                                        return (
                                            <React.Fragment key={mi}>
                                            <tr
                                                className="border-t border-gray-50 dark:border-slate-600 hover:bg-gray-50 dark:hover:bg-slate-600 cursor-pointer"
                                                onClick={() => setOpenMatch(isOpen ? null : key)}
                                            >
                                                <td className="px-3 py-2 font-medium text-gray-800 dark:text-gray-100">
                                                    <span className="text-gray-300 dark:text-gray-500 mr-1 text-xs">{isOpen ? '▾' : '▸'}</span>
                                                    {m.home}
                                                </td>
                                                <td className="px-3 py-2 font-medium text-gray-800 dark:text-gray-100">{m.away}</td>
                                                <td className="px-3 py-2 text-center font-mono text-gray-600 dark:text-gray-300">
                                                    {Math.round(primary.pred_home)}–{Math.round(primary.pred_away)}
                                                </td>
                                                <td className="px-3 py-2 text-center">
                                                    <OutcomeBadge outcome={primary.outcome} />
                                                </td>
                                                <td className="px-3 py-2 text-center font-mono text-gray-700 dark:text-gray-300">
                                                    {act ? <>{act.home}–{act.away} <OutcomeBadge outcome={m.actual_outcome} /></> : '—'}
                                                </td>
                                                <td className="px-3 py-2 text-center">
                                                    {correct === null
                                                        ? <span className="text-gray-300">—</span>
                                                        : correct
                                                            ? <span className="text-green-600 font-bold">✓</span>
                                                            : <span className="text-red-500 font-bold">✗</span>}
                                                </td>
                                            </tr>
                                            {isOpen && (
                                                <tr className="border-t border-gray-100 dark:border-slate-500">
                                                    <td colSpan={6} className="p-0">
                                                        <FeatureTable match={m} />
                                                    </td>
                                                </tr>
                                            )}
                                            </React.Fragment>
                                        )
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )
            })}
        </div>
    )
}

// ── Newsletter signup ──────────────────────────────────────────────────────────

// Brevo subscription form ID — no API key needed, safe to embed
// Set GATSBY_BREVO_FORM_ID in .env.production (from your Brevo subscription form URL)
const BREVO_FORM_ID = process.env.GATSBY_BREVO_FORM_ID || ""

function NewsletterSignup() {
    const [email,  setEmail]  = React.useState("")
    const [status, setStatus] = React.useState(null) // null | 'loading' | 'ok' | 'error'

    const submit = async (e) => {
        e.preventDefault()
        if (!BREVO_FORM_ID) { setStatus("error"); return }
        setStatus("loading")
        try {
            // mode: 'no-cors' — request goes through but response is opaque (by design)
            await fetch(`https://sibforms.com/serve/${BREVO_FORM_ID}`, {
                method: "POST",
                mode: "no-cors",
                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                body: new URLSearchParams({ EMAIL: email, email_address_check: "", locale: "fr" }).toString(),
            })
            setStatus("ok")
        } catch {
            setStatus("error")
        }
    }

    return (
        <div className="bg-red-50 dark:bg-slate-700 border border-red-100 dark:border-slate-600 rounded-xl px-5 py-4 mb-6">
            <p className="text-sm font-bold text-red-900 dark:text-white mb-1">🏉 Get predictions by email</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mb-3">Subscribe to receive an update each time new predictions are published.</p>
            {status === "ok" ? (
                <p className="text-sm text-green-700 dark:text-green-300 font-medium">Check your inbox to confirm your subscription!</p>
            ) : (
                <form onSubmit={submit} className="flex gap-2">
                    <input
                        type="email"
                        required
                        value={email}
                        onChange={e => setEmail(e.target.value)}
                        placeholder="your@email.com"
                        className="flex-1 text-sm rounded-lg border border-gray-200 dark:border-slate-500 bg-white dark:bg-slate-600 text-gray-800 dark:text-white px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-red-900 dark:focus:ring-white"
                    />
                    <button
                        type="submit"
                        disabled={status === "loading"}
                        className="px-4 py-1.5 text-sm font-bold rounded-lg bg-red-900 dark:bg-white text-white dark:text-red-900 hover:bg-red-800 dark:hover:bg-gray-100 disabled:opacity-50 transition-colors"
                    >
                        {status === "loading" ? "…" : "Subscribe"}
                    </button>
                    {status === "error" && <p className="text-xs text-red-600 dark:text-red-400 mt-1">Something went wrong, please try again.</p>}
                </form>
            )}
        </div>
    )
}

// ── Page ───────────────────────────────────────────────────────────────────────

const CHAMPS = [
    { id: 'top14', label: 'Top 14' },
    { id: 'prod2', label: 'Pro D2' },
]

const TABS = [
    { id: 'predictions', label: 'Predictions' },
    { id: 'history',     label: 'History'     },
]

function TabBar({ tabs, active, onChange }) {
    return (
        <div className="flex">
            {tabs.map(t => (
                <button
                    key={t.id}
                    onClick={() => onChange(t.id)}
                    className={`px-4 py-2.5 text-sm font-bold border-b-2 transition-colors ${active === t.id
                        ? 'border-red-900 dark:border-white text-red-900 dark:text-white'
                        : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-red-900 dark:hover:text-white'
                    }`}
                >
                    {t.label}
                </button>
            ))}
        </div>
    )
}

const PredictionsPage = () => {
    const [data,      setData]      = React.useState(null)
    const [loading,   setLoading]   = React.useState(true)
    const [error,     setError]     = React.useState(false)
    const [champ,     setChamp]     = React.useState('top14')
    const [activeTab, setActiveTab] = React.useState('predictions')

    React.useEffect(() => {
        fetch('/predictions.json')
            .then(r => { if (!r.ok) throw new Error(); return r.json() })
            .then(d => { setData(d); setLoading(false) })
            .catch(() => { setError(true); setLoading(false) })
    }, [])

    const champData = data?.[champ]

    return (
        <Layout>
            <div className="flex flex-grow flex-col mx-auto w-full px-4 sm:px-10 py-8 max-w-4xl">
                <h1 className="font-bold text-3xl text-red-900 dark:text-white mb-1">
                    🏉 Predictions
                </h1>
                <p className="text-gray-500 dark:text-gray-400 text-sm mb-6">
                    Match outcome predictions based on a statistical model (ELO, recent form, lineups). Outcome is derived from score predictions — H/D/A win probabilities are shown for reference.
                </p>

                <NewsletterSignup />

                {/* Championship selector */}
                <div className="flex gap-2 mb-4">
                    {CHAMPS.map(c => (
                        <button
                            key={c.id}
                            onClick={() => setChamp(c.id)}
                            className={`px-5 py-1.5 rounded-full text-sm font-bold border-2 transition-colors ${champ === c.id
                                ? 'bg-red-900 dark:bg-white border-red-900 dark:border-white text-white dark:text-red-900'
                                : 'border-gray-300 dark:border-slate-500 text-gray-500 dark:text-gray-400 hover:border-red-900 dark:hover:border-white hover:text-red-900 dark:hover:text-white'
                            }`}
                        >
                            {c.label}
                        </button>
                    ))}
                </div>

                {/* Content tabs */}
                <div className="border-b border-gray-200 dark:border-slate-600 mb-6">
                    <TabBar tabs={TABS} active={activeTab} onChange={setActiveTab} />
                </div>

                {/* Content */}
                {loading && <p className="text-center py-12 text-gray-400">Loading...</p>}
                {error   && <p className="text-center py-12 text-gray-400">No predictions available yet.</p>}
                {champData && (
                    <>
                        {activeTab === 'predictions' && <PredictionsTab current={champData.current} />}
                        {activeTab === 'history'     && <HistoryTab history={champData.history} stats={champData.stats} />}
                        <p className="text-xs text-gray-400 text-center mt-8">
                            Generated on {data.generated_at}
                        </p>
                    </>
                )}
            </div>
        </Layout>
    )
}

export const Head = () => (
    <Seo
        page="Predictions"
        description="Top 14 and Pro D2 match outcome predictions based on a statistical model. Outcome derived from score predictions."
        type="website"
        path="/predictions"
    />
)

export default PredictionsPage
